// Log the result summary
const result = $('Run Goal Agent Full Cycle').first().json;
return [{
  json: {
    timestamp: result.timestamp,
    phase: result.phase,
    experiments_created: result.experiments_created,
    experiments_started: result.experiments_started,
    contacts_enrolled: result.contacts_enrolled,
    experiments_concluded: result.experiments_concluded,
    signals_discovered: result.signals_discovered,
    orders_attributed: result.orders_attributed,
    summary: `Goal Agent: +${result.experiments_created} new experiments, ${result.contacts_enrolled} contacts enrolled, ${result.experiments_concluded} concluded, ${result.signals_discovered} signals discovered`
  }
}];
